import React, { useState, useEffect } from 'react';
import { Link } from 'react-scroll';
import './Navbar.css';

const Navbar = () => {
  const [sticky, setSticky] = useState(false);
  const [mobileMenu, setMobileMenu] = useState(false);

  const toggleMenu = () => {
    setMobileMenu(!mobileMenu);
  };

  useEffect(() => {
    const handleScroll = () => {
      setSticky(window.scrollY > 50);
    };

    window.addEventListener('scroll', handleScroll);
    return () => {
      window.removeEventListener('scroll', handleScroll);
    };
  }, []);

  // Close mobile menu when clicking a link
  const closeMenu = () => {
    setMobileMenu(false);
  };

  return (
    <nav className={`container ${sticky ? 'dark-nav' : ''}`}>
      <Link to="hero" smooth={true} offset={0} duration={500} onClick={closeMenu}>
        <div className="logo">
          <i className="fas fa-water"></i>
          <span>Echoes</span>
        </div>
      </Link>
      <ul className={mobileMenu ? 'mobile-menu' : 'hide-mobile-menu'}>
        <li>
          <Link to="hero" smooth={true} offset={0} duration={500} onClick={closeMenu}>
            Home
          </Link>
        </li>
        <li>
          <Link to="features" smooth={true} offset={-100} duration={500} onClick={closeMenu}>
            Features
          </Link>
        </li>
        <li>
          <Link to="how-it-works" smooth={true} offset={-100} duration={500} onClick={closeMenu}>
            How It Works
          </Link>
        </li>
        <li>
          <Link to="testimonials" smooth={true} offset={-100} duration={500} onClick={closeMenu}>
            Testimonials
          </Link>
        </li>
        <li>
          <Link to="pricing" smooth={true} offset={-100} duration={500} onClick={closeMenu}>
            Pricing
          </Link>
        </li>
        <li>
          <Link to="contact" smooth={true} offset={-100} duration={500} className='btn' onClick={closeMenu}>
            Contact
          </Link>
        </li>
      </ul>
      <div className="auth-buttons">
        <Link to="login" smooth={true} offset={0} duration={500} onClick={closeMenu}>
          <button className="btn-outline">Log In</button>
        </Link>
        <Link to="signup" smooth={true} offset={0} duration={500} onClick={closeMenu}>
          <button className="btn-primary">Sign Up</button>
        </Link>
      </div>
      <img 
        src="data:image/svg+xml;base64," 
        alt="Menu Icon" 
        className='menu-icon' 
        onClick={toggleMenu} 
      />
    </nav>
  );
};

export default Navbar;
